        {
          "from": "requirement_v1",
          "to": "procedure_v1",
          "type": "supports",
          "status": "proposed",
          "evidence_refs": [
            {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "编制首笔300万元资金的详细预算计划"}
          ]
        }
      ]
    },
    "workflows": [
      {
        "spec": {
          "id": "conv_5ca3f6271b31_w1",
          "task": "根据政策申报书文档，编制指定首笔拨付金额的阶段性预算明细表（Excel兼容：科目/金额/占比/说明），并附不超过500字的执行说明",
          "parameters": {
            "input_docx_path": "申报书.doc/x 路径（未来用户输入）",
            "first_payment_amount_yuan": "首笔拨付金额（例：3000000）",
            "period_months": "预算覆盖周期（默认6）",
            "output_xlsx_path": "输出工作簿路径"
          },
          "requirements": [
            {
              "text": "预算须覆盖第一阶段（至首个里程碑节点）全部支出，列明科目金额、测算依据、支出时序与对应交付物",
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "预算须覆盖第一阶段（至首个里程碑节点）所需全部支出，包括但不限于人员劳务、设备购置/租赁、材料费、测试化验加工费、差旅/会议、出版/知识产权、专家咨询、管理分摊等科目，列明各科目金额、测算依据、支出时序与对应交付物。"}
              ]
            },
            {
              "text": "输出为Excel兼容表格结构，含科目、金额、占比、说明三栏，并附500字以内执行说明",
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "格式为Excel兼容的表格结构（含科目、金额、占比、说明三栏），附500字以内执行说明。"}
              ]
            },
            {
              "text": "未指定项按通用默认：预算周期为立项后6个月内，符合上海市科委专项资金管理办法",
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "预算周期为立项后6个月内，符合上海市科委专项资金管理办法。"}
              ]
            }
          ],
          "conditions": [
            "输入docx可解压并文本化",
            "申报书披露科目级预算或比例上限，作为分配合规依据"
          ],
          "preserved_state": [],
          "steps": [
            {
              "id": "s1",
              "purpose": "抽取申报书中的预算约束",
              "input_refs": ["input_docx_path"],
              "preconditions": ["input_docx_path存在且为zip式docx"],
              "operation": "用zipfile读取word/document.xml，去标签得到全文，正则抽取专项资金总额、首年金额、劳务费上限比例、各科目年度预算、里程碑日期",
              "output_refs": ["extracted_constraints"],
              "postconditions": ["抽取结果非空并保留命中片段原文"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "依据《合生纪申报1000万政策》中明确的“科委按里程碑阶段性支付”机制及申报书所载项目实施计划"}
              ],
              "support_status": "proposed"
            },
            {
              "id": "s2",
              "purpose": "编制科目级预算明细",
              "input_refs": ["extracted_constraints", "first_payment_amount_yuan", "period_months"],
              "preconditions": ["s1完成"],
              "operation": "按申报书披露科目与上限分配首笔金额，逐项给出测算依据、支出时序与交付物，合计等于首笔金额",
              "output_refs": ["budget_rows"],
              "postconditions": ["各科目合计等于首笔金额", "劳务费不超过披露上限比例"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "编制首笔300万元资金的详细预算计划"}
              ],
              "support_status": "proposed"
            },
            {
              "id": "s3",
              "purpose": "输出Excel兼容交付文件",
              "input_refs": ["budget_rows", "output_xlsx_path"],
              "preconditions": ["s2完成"],
              "operation": "写出工作簿（预算明细表 + 执行说明），表头为科目/金额/占比/说明，执行说明不超过500字",
              "output_refs": ["output_xlsx_path"],
              "postconditions": ["文件存在且可读回", "三栏表头齐全", "执行说明字数≤500"],
              "asset_ids": [],
              "evidence_refs": [
                {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "格式为Excel兼容的表格结构（含科目、金额、占比、说明三栏），附500字以内执行说明。"}
              ],
              "support_status": "proposed"
            }
          ],
          "control_flow": {
            "dependencies": [["s1", "s2"], ["s2", "s3"]],
            "branches": [],
            "repair_loops": [
              {
                "from": "s3",
                "to": "s2",
                "max_iterations": 1,
                "exit_condition": "合计不等于首笔金额时重分配一次，仍不符则停止并报告剩余偏差"
              }
            ]
          },
          "failure_handling": [
            "若申报书未披露科目级预算，则按用户列举科目等比例分配并在输出中显式标注该假设"
