          "checks": [
            "各科目金额合计等于首笔拨付金额",
            "劳务费不超过申报书披露的比例上限（若披露）",
            "表头含科目、金额、占比、说明",
            "执行说明字数≤500"
          ],
          "asset_refs": [],
          "evidence_refs": [
            {"source_id": "conv_5ca3f6271b31", "turn_index": 0, "role": "user", "quote": "请作为公司项目负责人，依据《合生纪申报1000万政策》中明确的“科委按里程碑阶段性支付”机制及申报书所载项目实施计划，编制首笔300万元资金的详细预算计划。"}
          ],
          "unknowns": [
            "申报书是否披露科目级年度预算与劳务费比例上限（决定s2是约束映射还是等比例假设）"
